arguments.content:
import pandas as pd
pool_df = pd.read_csv('b3_te_zt_extrapolation_pool.csv')
for cid in ['c018', 'c064', 'c006', 'c043', 'c074']:
    print(f"\n{cid} features:")
    row = pool_df[pool_df['candidate_id'] == cid].iloc[0]
    for c in row.index:
        if c not in ['candidate_id', 'T'] and row[c] > 0.01:
            print(f"{c}: {row[c]}")

